'use strict';

const express = require('express');
const cors = require('cors');

const ALLOWED_ORIGINS = new Set(['https://one.example', 'https://two.example']);

// Origin allowlist function: exactly the two origins above, credentials enabled.
function corsOrigin(origin, callback) {
  if (ALLOWED_ORIGINS.has(origin)) {
    return callback(null, true);
  }
  // Not in the allowlist: no CORS headers will be emitted for this request.
  return callback(null, false);
}

const corsOptions = {
  origin: corsOrigin,
  credentials: true,
  exposedHeaders: ['X-Total-Count'],
  methods: ['GET', 'POST', 'PATCH'],
};

const app = express();
app.use(cors(corsOptions));

const items = [
  { id: 1, name: 'alpha' },
  { id: 2, name: 'beta' },
];

app.get('/items', (_req, res) => {
  res.set('X-Total-Count', String(items.length));
  res.json(items);
});

app.post('/items', express.json(), (req, res) => {
  const item = { id: items.length + 1, name: req.body.name ?? 'unnamed' };
  items.push(item);
  res.set('X-Total-Count', String(items.length));
  res.status(201).json(item);
});

app.patch('/items/:id', express.json(), (req, res) => {
  const item = items.find((i) => i.id === Number(req.params.id));
  if (!item) return res.status(404).json({ error: 'not found' });
  Object.assign(item, req.body);
  res.set('X-Total-Count', String(items.length));
  res.json(item);
});

module.exports = { app, ALLOWED_ORIGINS };

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`listening on :${port}`));
}

