'use strict';

const request = require('supertest');
const { app } = require('./app');

describe('CORS configuration', () => {
  describe('preflight (OPTIONS)', () => {
    test.each(['https://one.example', 'https://two.example'])(
      'echoes allowed origin %s instead of *',
      async (origin) => {
        const res = await request(app)
          .options('/items')
          .set('Origin', origin)
          .set('Access-Control-Request-Method', 'POST');

        expect(res.status).toBe(204);
        // Credentials mode forbids wildcard: must echo the exact origin.
        expect(res.headers['access-control-allow-origin']).toBe(origin);
        expect(res.headers['access-control-allow-origin']).not.toBe('*');
        expect(res.headers['access-control-allow-credentials']).toBe('true');
        expect(res.headers.vary).toContain('Origin');
      },
    );

    test('allows only GET, POST, PATCH', async () => {
      const res = await request(app)
        .options('/items')
        .set('Origin', 'https://one.example')
        .set('Access-Control-Request-Method', 'PATCH');

      expect(res.headers['access-control-allow-methods'])
        .toEqual(expect.arrayContaining(['GET', 'POST', 'PATCH'].map(String)));
      expect(res.headers['access-control-allow-methods']).toMatch(/^(GET,POST,PATCH|GET, POST, PATCH)$/);
    });

    test('disallowed origin gets NO CORS headers on preflight', async () => {
      const res = await request(app)
        .options('/items')
        .set('Origin', 'https://evil.example')
        .set('Access-Control-Request-Method', 'POST');

      expect(res.headers['access-control-allow-origin']).toBeUndefined();
      expect(res.headers['access-control-allow-credentials']).toBeUndefined();
      expect(res.headers['access-control-allow-methods']).toBeUndefined();
    });
  });

  describe('simple GET', () => {
    test('allowed origin gets data plus Vary: Origin and exposed headers', async () => {
      const res = await request(app)
        .get('/items')
        .set('Origin', 'https://two.example');

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThan(0);

      // Echoed origin (never * with credentials).
      expect(res.headers['access-control-allow-origin']).toBe('https://two.example');

      // Vary must include Origin so caches key responses per-origin.
      expect(res.headers.vary).toContain('Origin');

      // Exposed header readable by non-credentialed browser JS.
      expect(res.headers['access-control-expose-headers']).toContain('X-Total-Count');
      expect(res.headers['x-total-count']).toBe('2');
    });

    test('disallowed origin: response still returns data but carries no CORS headers — the browser enforces CORS, not the server', async () => {
      const res = await request(app)
        .get('/items')
        .set('Origin', 'https://evil.example');

      expect(res.status).toBe(200);
      expect(res.body[0].name).toBe('alpha'); // server happily serves

      // Specifically assert absence of each CORS header.
      expect(res.headers).not.toHaveProperty('access-control-allow-origin');
      expect(res.headers).not.toHaveProperty('access-control-allow-credentials');
      expect(res.headers).not.toHaveProperty('access-control-expose-headers');
    });

    test('request without Origin header is unaffected', async () => {
      const res = await request(app).get('/items');
      expect(res.status).toBe(200);
      expect(res.headers).not.toHaveProperty('access-control-allow-origin');
    });
  });
});

